package org.rabochaya.projects;
import android.content.*;import android.database.sqlite.*;import android.graphics.*;import java.io.*;import java.util.*;
/** Offline-only image snapshot of the saved project composition; no KML or tile downloads. */
public final class CompositionCacheExport {
 private static final long MAX_BYTES=512L*1024*1024;
 private CompositionCacheExport(){}
 private static final class Group implements Closeable {
  final MapComposition.Layer model;OnlineTiles[] readers;TileSource[] sources;OfflineTiles local;BundledTiles bundled;
  Group(Context context,long project,MapComposition.Layer layer)throws IOException{model=layer;try{if("local".equals(layer.kind))local=new OfflineTiles(new File(context.getFilesDir(),"local_basemap_"+project+".mbtiles"));else if("bundled".equals(layer.kind))bundled=new BundledTiles(context.getAssets());else{TileSource source=layer.source();if(source==null)throw new IOException("Источник отсутствует в каталоге: "+layer.name);sources=source.leafs();readers=new OnlineTiles[sources.length];for(int i=0;i<sources.length;i++)readers[i]=new OnlineTiles(context,sources[i]);}}catch(Exception e){close();if(e instanceof IOException)throw (IOException)e;throw new IOException("Не удалось открыть слой: "+layer.name,e);}}
  public void close(){if(local!=null)local.close();if(readers!=null)for(OnlineTiles r:readers)if(r!=null)r.close();}
  void keys(TreeMap<String,int[]> keys)throws IOException{if(readers!=null){for(int i=0;i<readers.length;i++)for(int[] key:readers[i].keys()){int z=key[0],n=1<<z,first=key[2],last=first;if(sources[i].ellipsoid){first=Math.max(0,(int)Math.floor(MapMath.y(TileProjection.latitude(key[2]/(double)n,true))*n+1e-9));last=Math.min(n-1,(int)Math.ceil(MapMath.y(TileProjection.latitude((key[2]+1.0)/n,true))*n-1e-9)-1);}for(int y=first;y<=last;y++)add(keys,z,key[1],y);}}else if(local!=null){for(int[] key:local.keys())add(keys,key[0],key[1],key[2]);}else for(int z=1;z<=3;z++)for(int x=0;x<(1<<z);x++)for(int y=0;y<(1<<z);y++)add(keys,z,x,y);}
  Bitmap render(int z,int x,int y)throws IOException{if(readers!=null)return CacheExport.render(readers,sources,z,x,y);int sourceZoom=local!=null?local.zoomFor(z):bundled.zoomFor(z),sourceN=1<<sourceZoom,n=1<<z;double left=x/(double)n,top=y/(double)n,right=(x+1.0)/n,bottom=(y+1.0)/n;int firstX=Math.max(0,(int)Math.floor(left*sourceN)),lastX=Math.min(sourceN-1,(int)Math.ceil(right*sourceN)-1),firstY=Math.max(0,(int)Math.floor(top*sourceN)),lastY=Math.min(sourceN-1,(int)Math.ceil(bottom*sourceN)-1);if((long)(lastX-firstX+1)*(lastY-firstY+1)>32)throw new IOException("Для этого сочетания уровней нужно больше 32 исходных тайлов на выходной тайл");Bitmap result=null;try{Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);for(int sy=firstY;sy<=lastY;sy++)for(int sx=firstX;sx<=lastX;sx++){Bitmap tile=local!=null?local.tile(sourceZoom,sx,sy):bundled.tile(sourceZoom,sx,sy);if(tile==null)continue;try{if(result==null)result=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);float px=(float)((sx/(double)sourceN-left)*n*256),py=(float)((sy/(double)sourceN-top)*n*256),size=(float)(n/(double)sourceN*256);canvas.drawBitmap(tile,null,new RectF(px,py,px+size,py+size),paint);}finally{tile.recycle();}}return result;}catch(IOException|RuntimeException e){if(result!=null)result.recycle();throw e;}}
 }
 private static void add(TreeMap<String,int[]> keys,int z,int x,int y)throws IOException{keys.put(z+"/"+x+"/"+y,new int[]{z,x,y});if(keys.size()>20000)throw new IOException("Экспорт ограничен 20 000 выходных тайлов");}
 private static void meta(SQLiteDatabase db,String name,String value){ContentValues row=new ContentValues();row.put("name",name);row.put("value",value);db.insertOrThrow("metadata",null,row);}
 public static int write(Context context,MapComposition composition,File destination,CacheExport.Progress progress)throws IOException{if(composition==null)throw new IllegalArgumentException("Нужен состав карт");return RasterExportFile.replace(destination,tmp->prepared(context,composition,tmp,progress));}
 private static int prepared(Context context,MapComposition composition,File destination,CacheExport.Progress progress)throws IOException{ArrayList<Group> groups=new ArrayList<>();SQLiteDatabase out=null;boolean complete=false;try{TreeMap<String,int[]> keys=new TreeMap<>();for(MapComposition.Layer layer:composition.layers)if(layer.visible&&layer.opacity>0){Group group=new Group(context,composition.project,layer);groups.add(group);group.keys(keys);}if(keys.isEmpty())throw new IOException("В видимых слоях нет сохранённых тайлов");progress.update(0,keys.size());if(destination.exists()&&!destination.delete())throw new IOException("Не удалось подготовить временный экспорт");out=SQLiteDatabase.openOrCreateDatabase(destination,null);out.execSQL("CREATE TABLE metadata(name TEXT PRIMARY KEY,value TEXT)");out.execSQL("CREATE TABLE tiles(zoom_level INTEGER NOT NULL,tile_column INTEGER NOT NULL,tile_row INTEGER NOT NULL,tile_data BLOB NOT NULL,PRIMARY KEY(zoom_level,tile_column,tile_row))");meta(out,"name","Композиция слоёв");meta(out,"attribution",composition.attributions());meta(out,"format","png");meta(out,"type","baselayer");meta(out,"version","1.3");meta(out,"scheme","tms");int count=0,done=0,min=24,max=-1;long bytes=0;double[] bounds={180,90,-180,-90};out.beginTransaction();try{Paint paint=new Paint(Paint.FILTER_BITMAP_FLAG);for(int[] key:keys.values()){progress.update(done,keys.size());Bitmap result=null;try{for(Group group:groups){Bitmap layer=group.render(key[0],key[1],key[2]);if(layer==null)continue;try{if(result==null)result=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);paint.setAlpha(Math.round(group.model.opacity*255f/100f));new Canvas(result).drawBitmap(layer,0,0,paint);}finally{layer.recycle();}}if(result!=null){ByteArrayOutputStream encoded=new ByteArrayOutputStream();if(!result.compress(Bitmap.CompressFormat.PNG,100,encoded))throw new IOException("Не удалось сохранить изображение тайла");byte[] data=encoded.toByteArray();bytes+=data.length;if(bytes>MAX_BYTES)throw new IOException("Экспорт больше 512 МиБ");ContentValues row=new ContentValues();row.put("zoom_level",key[0]);row.put("tile_column",key[1]);row.put("tile_row",MapMath.tmsRow(key[0],key[2]));row.put("tile_data",data);out.insertOrThrow("tiles",null,row);count++;double n=1<<key[0];bounds[0]=Math.min(bounds[0],key[1]/n*360-180);bounds[1]=Math.min(bounds[1],MapMath.lat((key[2]+1.0)/n));bounds[2]=Math.max(bounds[2],(key[1]+1.0)/n*360-180);bounds[3]=Math.max(bounds[3],MapMath.lat(key[2]/n));min=Math.min(min,key[0]);max=Math.max(max,key[0]);}}finally{if(result!=null)result.recycle();}done++;}if(count==0)throw new IOException("Нет читаемых растровых тайлов");meta(out,"bounds",String.format(Locale.US,"%.9f,%.9f,%.9f,%.9f",bounds[0],bounds[1],bounds[2],bounds[3]));meta(out,"minzoom",Integer.toString(min));meta(out,"maxzoom",Integer.toString(max));out.setTransactionSuccessful();}finally{out.endTransaction();}out.close();out=null;progress.update(keys.size(),keys.size());complete=true;return count;}catch(Exception e){if(e instanceof IOException)throw (IOException)e;throw new IOException("Не удалось экспортировать состав карт: "+e.getMessage(),e);}finally{if(out!=null)out.close();for(Group group:groups)group.close();if(!complete)destination.delete();}}
}
